using System;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Windows.Media.Media3D;
namespace GearLab {
 // Independent normal-envelope construction for a single-wave rolling-element drive.
 public static class WaveFastModel {
  public static WaveParameters From(Parameters p){return new WaveParameters{Rolling=true,Ratio=(int)Math.Round(p.Ratio),BallDiameter=p.BallDiameter,ProfileRadius=p.Radius,Eccentric=p.Eccentric,Module=p.Module,Thickness=p.Thickness,RingWall=p.Wall,Bore=p.Shaft,OutputBore=p.OutputShaft,Clearance=p.Clearance,InputTorque=p.InputTorque,InputRpm=p.InputRpm,Efficiency=p.Efficiency,LoadTorque=p.LoadTorque};}
  public static Parameters Upgrade(Parameters p){if(p.Kind!=4||p.WaveScheme==1)return p;double oldRadius=p.Module*(p.Ratio+2.25);p.Ratio=Math.Max(6,Math.Min(120,Math.Round(p.Ratio)));double sn=Math.Sin(Math.PI/(p.Ratio+1));p.BallDiameter=Math.Max(2,Math.Min(6,oldRadius*sn/(1.03+.4*sn)));p.Eccentric=.2*p.BallDiameter;p.Radius=Math.Max(oldRadius,MinimumRadius(p)+.05);p.Thickness=Math.Max(p.Thickness,p.BallDiameter+2*p.Clearance);p.Wall=Math.Max(4,p.Wall);p.WaveScheme=1;p.Overall=0;p.AutoFit=false;return p;}
  public static double Radius(Parameters p){return p.Radius+p.Wall;}
  public static double MinimumRadius(Parameters p){return 1.03*p.BallDiameter/Math.Sin(Math.PI/(p.Ratio+1))+2*p.Eccentric;}
  public static bool Fit(Parameters p){if(p.Overall<=0)return true;double radius=p.Overall/2-p.Wall;if(radius<MinimumRadius(p)||radius>500)return false;var c=Engine.Clone(p);c.Radius=radius;if(!Calculate(c).Valid)return false;p.Radius=radius;return true;}
  public static PointF[] Track(Parameters p){int n=Math.Max(720,(int)(p.Ratio+1)*72);double b=p.BallDiameter/2,e=p.Eccentric,c=p.Radius-e-b;var pts=new PointF[n];for(int i=0;i<n;i++){double th=Engine.Tau*i/n,u=(p.Ratio+1)*th,s=Math.Sqrt(c*c-e*e*Math.Sin(u)*Math.Sin(u)),rho=e*Math.Cos(u)+s;double dr=-e*(p.Ratio+1)*Math.Sin(u)*(1+e*Math.Cos(u)/s),norm=Math.Sqrt(rho*rho+dr*dr);pts[i]=new PointF((float)(rho*Math.Sin(th)+(b+p.Clearance)*(rho*Math.Sin(th)-dr*Math.Cos(th))/norm),(float)(rho*Math.Cos(th)+(b+p.Clearance)*(rho*Math.Cos(th)+dr*Math.Sin(th))/norm));}return pts;}
  public static Point3D BallCentre(Parameters p,int i,double phase){double th=Engine.Tau*i/p.Ratio+phase/p.Ratio,u=th+phase,c=p.Radius-p.Eccentric-p.BallDiameter/2,rho=p.Eccentric*Math.Cos(u)+Math.Sqrt(c*c-p.Eccentric*p.Eccentric*Math.Sin(u)*Math.Sin(u));return new Point3D(rho*Math.Sin(th),rho*Math.Cos(th),p.Thickness/2);}
  public static Result Calculate(Parameters input){var p=Upgrade(Engine.Clone(input));var r=new Result{P=p};try{
   if(p.WaveScheme!=1)throw new Exception("Неизвестная схема ПТК.");if(p.Ratio!=Math.Round(p.Ratio)||p.Ratio<6||p.Ratio>120)throw new Exception("ПТК: целое передаточное число 6–120.");
   if(p.BallDiameter<2||p.BallDiameter>20||p.Eccentric<=0||p.Eccentric>p.BallDiameter*.24||p.Radius<MinimumRadius(p)||p.Radius>500)throw new Exception("Шарики Ø2–20 мм; эксцентриситет ≤ 0,24 диаметра. Радиус профиля нужен не меньше "+Engine.F(MinimumRadius(p))+" мм.");
   if(p.Thickness<p.BallDiameter+2*p.Clearance||p.Wall<4||p.Clearance<.02||p.Clearance>.5||p.Shaft<=0||p.OutputShaft<=0||p.InputRpm<0||p.InputTorque<0||p.Efficiency<=0||p.Efficiency>1||p.LoadTorque<0)throw new Exception("Проверьте толщину (≥ диаметр шарика + 2 зазора), стенку ≥4 мм, валы и двигатель.");
   double cam=p.Radius-p.Eccentric-p.BallDiameter;if(cam-p.Eccentric<=Math.Max(p.Shaft,p.OutputShaft)/2+4)throw new Exception("Валы и опора не помещаются в генераторе.");
   r.Wave=From(p);r.Actual=p.Ratio;r.Z1=(int)p.Ratio;r.Z2=r.Z1+1;r.Width=r.Height=2*Radius(p);r.Depth=p.Thickness+2*p.ModelCover+24;if(p.Overall>0&&r.Width>p.Overall+.025)r.Error("ПТК не помещается в заданный габарит.","Overall","Radius");r.Gear1=Enumerable.Range(0,128).Select(i=>new PointF((float)(cam*Math.Cos(Engine.Tau*i/128)),(float)(p.Eccentric+cam*Math.Sin(Engine.Tau*i/128)))).ToArray();r.Gear2=Track(p);
   r.Metric("Схема","ПТК · шарики · одна волна");r.Metric("Шарики / впадины",r.Z1+" / "+r.Z2);r.Metric("Диаметр шариков",Engine.F(p.BallDiameter)+" мм");r.Metric("Эксцентриситет",Engine.F(p.Eccentric)+" мм");r.Metric("Выходная скорость",Engine.F(-p.InputRpm/p.Ratio)+" об/мин");r.Metric("Момент при заданном КПД",Engine.F(p.InputTorque*p.Ratio*p.Efficiency)+" Н·м");r.Metric("Требуемый входной момент",Engine.F(p.LoadTorque/(p.Ratio*p.Efficiency))+" Н·м");
   r.Notes.Add("По схеме видео TrashRobotics: шарики в радиальных окнах выходного сепаратора, жёсткое кольцо и круглый эксцентрик. Базовый пример: i=17, шарики 6 мм, e=1,2 мм, радиус впадин 38 мм.");r.Notes.Add("Профиль построен как нормальная огибающая движения шарика; nвых=−nвх/i. Зазор добавлен по нормали. Износ, упругость, ресурс и допустимая нагрузка не рассчитаны.");
  }catch(Exception ex){r.Error(ex.Message,"Ratio","BallDiameter","Eccentric","Radius","Thickness");}return r;}
  public static void Add(CadAssembly a,Result r){var p=r.P;double outer=Radius(p),t=p.Thickness,plate=Math.Max(3,p.ModelCover),g=p.Clearance,cam=p.Radius-p.Eccentric-p.BallDiameter,pitch=cam+p.BallDiameter/2;var steel=Color.FromArgb(178,190,205);
   Func<string,string,string,Color,CadPart> part=(id,name,role,color)=>{var q=new CadPart("wave_"+id,name,role,color);a.Parts.Add(q);return q;};Action<CadPart,double,double,CadLoop,IEnumerable<CadLoop>> sec=(q,z,h,o,cuts)=>q.Sections.Add(new CadSection(z,z+h,o,cuts));double boltR=outer-p.Wall*.45,bolt=Math.Min(1.5,p.Wall*.18);var holes=Enumerable.Range(0,6).Select(i=>CadLoop.Round(boltR*Math.Cos(Engine.Tau*i/6),boltR*Math.Sin(Engine.Tau*i/6),bolt)).ToArray();
   var ring=part("ring","Жёсткое кольцо · "+r.Z2+" впадин","housing",Color.FromArgb(219,226,231));sec(ring,0,t,CadLoop.Round(0,0,outer),new[]{CadLoop.Polygon(r.Gear2)}.Concat(holes));
   var back=part("back","Моторный фланец","housing",Color.FromArgb(105,135,158));sec(back,-plate-g,plate,CadLoop.Round(0,0,outer),new[]{CadLoop.Round(0,0,p.Shaft/2+4)}.Concat(holes));
   var gen=part("generator","Круглый эксцентриковый генератор","gear",Color.FromArgb(47,139,199));sec(gen,0,t,CadLoop.Round(0,p.Eccentric,cam),new[]{CadLoop.Round(0,p.Eccentric,p.Shaft/2+3)});
   var input=part("input","Входной вал","shaft",steel);sec(input,-plate-g-14,plate+g+13,CadLoop.Round(0,0,p.Shaft/2),null);sec(input,-1,1,CadLoop.Round(0,0,p.Shaft/2+p.Eccentric+.5),null);sec(input,0,t,CadLoop.Round(0,p.Eccentric,p.Shaft/2),null);
   var bearing=part("input_bearing","Опора входного вала","bearing",steel);sec(bearing,0,Math.Min(t,5),CadLoop.Round(0,p.Eccentric,p.Shaft/2+3),new[]{CadLoop.Round(0,p.Eccentric,p.Shaft/2)});
   for(int i=0;i<(int)p.Ratio;i++){var c=BallCentre(p,i,0);a.Parts.Add(BearingDetail.Ball("wave_ball"+i,"Рабочий шарик ПТК "+(i+1),c.X,c.Y,c.Z,p.BallDiameter/2));}
   var output=part("output","Выходной фланец сепаратора и вал","gear",Color.FromArgb(234,139,42));double drum=pitch+p.BallDiameter*.22;sec(output,t+g,plate,CadLoop.Round(0,0,drum+.4),null);sec(output,t+g+plate,12,CadLoop.Round(0,0,p.OutputShaft/2),null);
   double half=Math.Asin((p.BallDiameter/2+2*g)/(pitch-p.BallDiameter*.22));for(int i=0;i<(int)p.Ratio;i++){double start=Math.PI/2+Engine.Tau*i/p.Ratio+half,end=Math.PI/2+Engine.Tau*(i+1)/p.Ratio-half;var pts=new List<PointF>();for(int j=0;j<=6;j++)pts.Add(Engine.Polar(drum,start+(end-start)*j/6));for(int j=6;j>=0;j--)pts.Add(Engine.Polar(pitch-p.BallDiameter*.22,start+(end-start)*j/6));sec(output,0,t+g,CadLoop.Polygon(pts.ToArray()),null);}
   var mesh=new MeshWriter();var disk=output.Sections[0];var shaft=output.Sections[1];var webs=output.Sections.Skip(2).ToList();SceneMesher.Cap(mesh,disk.Outer,webs.Select(s=>s.Outer),disk.Bottom,false);SceneMesher.Sides(mesh,disk.Outer,disk.Bottom,disk.Top,false);SceneMesher.Cap(mesh,disk.Outer,new[]{shaft.Outer},disk.Top,true);SceneMesher.Sides(mesh,shaft.Outer,shaft.Bottom,shaft.Top,false);SceneMesher.Cap(mesh,shaft.Outer,new CadLoop[0],shaft.Top,true);foreach(var web in webs){SceneMesher.Cap(mesh,web.Outer,new CadLoop[0],web.Bottom,false);SceneMesher.Sides(mesh,web.Outer,web.Bottom,web.Top,false);}output.MeshOverride=mesh.Finish();output.SectionUnion=true;
   var outBearing=part("output_bearing","Опора выходного сепаратора","bearing",steel);sec(outBearing,t+2*g+plate,5,CadLoop.Round(0,0,p.OutputShaft/2+4),new[]{CadLoop.Round(0,0,p.OutputShaft/2)});
   var front=part("front","Передняя крышка · посадка выходной опоры","housing",Color.FromArgb(105,135,158));sec(front,t+2*g+plate,5,CadLoop.Round(0,0,outer),new[]{CadLoop.Round(0,0,p.OutputShaft/2+4)}.Concat(holes));
   for(int i=0;i<6;i++){var h=holes[i];var q=part("bolt"+i,"Винт фланца","fastener",steel);sec(q,-plate-g,t+2*plate+3*g+5,CadLoop.Round(h.X,h.Y,bolt*.85),null);}
   a.Notes.Add("ПТК: сферические тела качения, профильное кольцо и выходной сепаратор. Сепаратор, радиальные окна, фланец и выходной вал образуют одно связное тело. Крепёж без резьбы.");
  }
 }
}
